  const BILL_PRINT_CSS='body{margin:0;padding:8px;font:12px/1.45 monospace;color:#000;background:#fff}.bill{max-width:76mm;margin:0 auto}.bill-tag,.bill-head,.bill-center{text-align:center;margin:4px 0;font-weight:700;letter-spacing:.08em}.bill-store{text-align:center;font-size:15px;margin:2px 0}.bill-small{margin:2px 0;text-align:center}.bill-rule{border-top:1px dashed #000;margin:6px 0}.bill-row{display:flex;justify-content:space-between;gap:8px;margin:2px 0}.bill-cols span:first-child{flex:1}.bill-cols span{min-width:40px;text-align:right}.bill-cols span:first-child{text-align:left}.bill-row.total{font-size:14px}.bill-note{font-size:10.5px;margin:4px 0}';
