  function restaurantValueLabel(o){if(o&&o.status==="Delivered")return"Completed order value estimate";if(o&&o.status==="Cancelled")return"Cancelled order value";return"Active order value"}
  function restaurantBreakdown(o){const terms=orderTerms(o);if(terms){const c=terms.customer,r=terms.restaurant,own=Number(c.restaurantDiscountPaise||0),platform=Number(c.platformDiscountPaise||0),pct=(Number(r.commissionBps||0)/100).toFixed(2).replace(/\.00$/,"");return'<div class="stack"><div class="settings-row"><span>Order value (menu items)</span><strong>'+moneyPaise(c.itemSubtotalPaise)+'</strong></div>'+(own?'<div class="settings-row"><span>Your offer (you fund)</span><strong>-'+moneyPaise(own)+'</strong></div>':'')+(platform?'<div class="settings-row"><span>Scraveit offer <small class="caption" style="display:block">Paid by Scraveit, not deducted from you</small></span><strong>'+moneyPaise(platform)+'</strong></div>':'')+'<div class="settings-row"><span>Scraveit commission ('+h(pct)+'% of '+moneyPaise(r.commissionBasePaise)+')</span><strong>-'+moneyPaise(r.commissionPaise)+'</strong></div>'+(r.rushFeeSharePaise?'<div class="settings-row"><span>Busy-kitchen fee <small class="caption" style="display:block">Your share of the fee the customer paid when your kitchen was busy</small></span><strong>+'+moneyPaise(r.rushFeeSharePaise)+'</strong></div>':'')+'<div class="divider"></div><div class="settings-row"><span><strong>You receive</strong></span><strong>'+moneyPaise(r.receivablePaise)+'</strong></div><p class="caption">Locked when the customer placed this order. Later changes to your plan or offers do not change it. Refunds or adjustments, if any, appear in your settlement statement.</p></div>'}const netKnown=commissionKnown(),gross=restaurantOrderValue(o),payable=restaurantDisplayValue(o),commissionAmount=netKnown?Math.max(0,Math.round((gross-payable)*100)/100):0,bps=netKnown?Number(state.restaurant&&state.restaurant.commissionBps):0,pct=netKnown?(bps/100).toFixed(2).replace(/\.00$/,""):"";return'<div class="stack"><div class="settings-row"><span>Menu item subtotal snapshot</span><strong>'+money(gross)+'</strong></div>'+(netKnown?'<div class="settings-row"><span>Commission ('+h(pct)+'%)</span><strong>-'+money(commissionAmount)+'</strong></div>':'')+'<div class="divider"></div><div class="settings-row"><span><strong>'+h(restaurantValueLabel(o))+(netKnown?' (after commission)':'')+'</strong></span><strong>'+money(payable)+'</strong></div><p class="caption">'+(netKnown?'Commission already deducted using this restaurant\'s rate. Adjustments, refunds, COD and settlement are still not calculated on this screen; authoritative finance records come from the platform ledger.':'Order-value projection only. Commission, adjustments, refunds, COD and settlement are not calculated on this screen; authoritative finance records come from the platform ledger.')+'</p></div>'}
  function awaitingVerifiedPayment(o){return o&&o.paymentMethod!=="cod"&&o.paymentState!=="paid"&&o.paymentState!=="refunded"}
