    const today='<section class="today-card"><span class="caption">Today</span><strong class="today-total">'+money(activeValue)+'</strong><span class="supporting">'+activeToday.length+' active · '+tod.length+' order'+(tod.length===1?'':'s')+' today · '+(commissionKnown()?'after commission':'order value')+'</span><div class="today-meta"><span>'+(ratingCount?rating.toFixed(1)+' ★ · '+ratingCount+' review'+(ratingCount===1?'':'s'):'No ratings yet')+'</span><button class="text-button" data-action="go" data-route="earningsReport">Earnings report</button></div></section>';
