  function orderRow(o){const tone=o.status==="Order placed"?"new":["Accepted","Preparing"].includes(o.status)?"kitchen":["Ready for pickup","Assigned"].includes(o.status)?"ready":o.status==="Cancelled"?"cancelled":"done",at=Number(o.createdAt||0),time=at?new Date(at).toLocaleTimeString("en-IN",{hour:"numeric",minute:"2-digit"}):"",items=(o.items||[]),count=items.reduce((n,i)=>n+Number(i.quantity||1),0);return'<article class="card order-row tone-'+tone+'" data-action="open-order" data-order-id="'+h(o.id)+'" role="button" tabindex="0"><div class="order-row-top"><span class="order-pill">'+h(o.status==="Order placed"?"New order":o.status||"Order placed")+'</span><span class="caption">'+h(time)+'</span></div><div class="order-row-main"><div class="grow"><h3 class="card-title">#'+h(String(o.id||"").slice(-6))+' · '+h(count)+' item'+(count===1?'':'s')+'</h3><p class="supporting">'+h(items.map(i=>(i.quantity||1)+'× '+i.name).slice(0,3).join(" · "))+'</p></div><strong class="order-row-total">'+money(o.total||o.pricing&&o.pricing.total||0)+'</strong></div>'+(awaitingVerifiedPayment(o)?'<p class="caption">Awaiting online payment</p>':'')+(riderComing(o)?'<p class="rider-coming">'+riderComing(o)+'</p>':'')+'</article>'}
  const ORDER_GROUPS=[["all","All",o=>true],["new","New",o=>o.status==="Order placed"],["kitchen","Preparing",o=>["Accepted","Preparing"].includes(o.status)],["ready","Ready",o=>["Ready for pickup","Assigned"].includes(o.status)],["done","Done",o=>["Handed to rider","Out for delivery","Near you","Arrived","Delivered","Cancelled"].includes(o.status)]];
