  function nextStatus(o){if(!o||awaitingVerifiedPayment(o))return"";if(o.status==="Order placed"&&permission("orders"))return"Accepted";if(o.status==="Accepted"&&permission("orders"))return"Preparing";if(o.status==="Preparing"&&permission("orders"))return"Ready for pickup";if(o.status==="Assigned"&&o.riderId&&o.riderArrivalVerified===true&&permission("handover"))return"Handed to rider";return""}
