  function riderAssignmentCopy(o){if(o.riderName)return'<div class="notice info"><strong>Rider reserved:</strong>&nbsp;'+h(o.riderName)+(riderComing(o)?'<span class="caption" style="display:block;font-weight:700">'+riderComing(o)+'</span>':'')+(o.status==="Accepted"||o.status==="Preparing"?'<span class="caption" style="display:block">Pickup remains locked until this order is ready.</span>':o.status==="Assigned"&&o.riderArrivalVerified!==true?'<span class="caption" style="display:block">Waiting for verified rider arrival at the restaurant.</span>':o.status==="Assigned"?'<span class="caption" style="display:block">Rider arrival verified. Handover is unlocked.</span>':'')+'</div>';if(["Accepted","Preparing","Ready for pickup"].includes(o.status))return'<p class="caption">Finding the nearest available rider now.</p>';return'<p class="caption">A rider is assigned after the restaurant accepts the order.</p>'}
  function screenOrder(){const o=order();if(!o)return'<main class="screen"><div class="content page">'+top("Order unavailable","Refresh and try again")+empty("orders","Order not found","This account cannot access the order.","refresh","Refresh")+'</div>'+nav()+'</main>';const next=nextStatus(o);return'<main class="screen"><div class="content page">'+top("Order "+o.id,o.status)+'<section class="card stack"><div class="cluster between"><span class="status">'+h(o.status)+'</span><strong>'+money(restaurantDisplayValue(o))+(commissionKnown()?' payable (after commission)':' order value')+'</strong></div>'+paymentPendingNotice(o)+'<div class="stack">'+(o.items||[]).map(i=>'<div class="settings-row"><span class="grow"><strong>'+h((i.quantity||1)+'× '+i.name)+'</strong><span class="caption" style="display:block">'+h(i.note||"")+'</span></span><span>'+money((Number(i.price||0)+Number(i.variantPrice||0)+Number(i.addOnTotal||0))*Number(i.quantity||1))+'</span></div>').join("")+'</div><div class="divider"></div>'+restaurantBreakdown(o)+'<button class="button tonal full" data-action="open-bill" data-order-id="'+h(o.id)+'">View bill</button></section><section class="card stack"><h2 class="section-title">Delivery</h2><p class="supporting">'+h(o.address&&o.address.address||o.address&&o.address.details||"Delivery address")+'</p>'+riderAssignmentCopy(o)+'</section><section class="card stack"><h2 class="section-title">Communication</h2><p class="supporting">Use Scraveit chat instead of exchanging personal mobile numbers.</p><div class="cluster wrap"><button class="button tonal grow" data-action="open-chat" data-channel="customerRestaurant" data-order-id="'+h(o.id)+'">Chat customer</button>'+(o.contactProxy&&o.contactProxy.restaurantToCustomer?'<a class="button secondary grow" href="tel:'+h(o.contactProxy.restaurantToCustomer)+'">Secure call customer</a>':'')+(o.riderId?'<button class="button tonal grow" data-action="open-chat" data-channel="restaurantRider" data-order-id="'+h(o.id)+'">Chat rider</button>':'')+(o.riderId&&o.contactProxy&&o.contactProxy.restaurantToRider?'<a class="button secondary grow" href="tel:'+h(o.contactProxy.restaurantToRider)+'">Secure call rider</a>':'')+'</div></section>'+(o.status==="Order placed"&&permission("orders")&&!awaitingVerifiedPayment(o)?'<div class="cluster wrap"><button class="button primary grow" data-action="advance-order" data-order-id="'+h(o.id)+'" data-status="Accepted">Accept order</button><button class="button danger grow" data-action="decline-order" data-order-id="'+h(o.id)+'">Decline</button></div>':next?'<button class="button primary full" data-action="advance-order" data-order-id="'+h(o.id)+'" data-status="'+h(next)+'">'+h(next)+'</button>':o.status==="Order placed"&&permission("orders")?'<button class="button tonal full" type="button" disabled>Waiting for verified payment</button>':'')+'</div>'+nav()+'</main>'}
  function menuRow(item){const image=String(item.imageUrl||item.image||"");return'<article class="card entity-row"><div class="entity-image" style="display:grid;place-items:center;overflow:hidden">'+(image?'<img src="'+h(image)+'" alt="" style="width:100%;height:100%;object-fit:cover">':icon("menu","large"))+'</div><div class="grow"><div class="cluster wrap"><h3 class="card-title">'+h(item.name||"Untitled item")+'</h3><span class="status '+(item.archived?'danger':item.available===false?'warning':'success')+'">'+(item.archived?'Archived':item.available===false?'Out of stock':'Available')+'</span></div><p class="supporting">'+h(item.category||"Menu")+' · '+(permission("menu")&&!SELLS_PACKAGED&&!item.archived?'<button type="button" class="price-tap" data-action="quick-price" data-item-id="'+h(item.id)+'">'+money(item.price)+' '+icon("edit","small")+'</button>':money(item.price))+'</p>'+(Number(item.price)>0&&!item.archived?'<p class="caption">You get <strong class="money-good">'+OM.rupees(OM.payout(Math.round(Number(item.price)*100),0,offerCommissionBps()).receive)+'</strong> per dish</p>':'')+'<p class="caption">'+h(item.diet==="nonveg"?"Non-vegetarian":item.diet==="egg"?"Contains egg":"Vegetarian")+'</p></div>'+(permission("menu")?'<button class="button tonal small" data-action="edit-menu-item" data-item-id="'+h(item.id)+'">Edit</button>':'')+'</article>'}
