  function screenMenu(){const all=menuItems(true);return'<main class="screen"><div class="content page">'+top("Menu","Create, edit, stock, restore or remove items",permission("menu")?'<button class="button primary small" data-action="new-menu-item">'+icon("plus")+' Add</button>':'')+banner()+(all.length?'<div class="input-wrap"><span class="input-icon">'+icon("search")+'</span><input id="menu-search" class="input with-icon" value="'+h(state.menuQuery)+'" placeholder="Search active or archived items" autocomplete="off" enterkeyhint="search"></div><div id="menu-results">'+menuResultsMarkup()+'</div>':empty("menu","No menu items","Tap Add to create the first menu item.",permission("menu")?"new-menu-item":"","Add item"))+'</div>'+nav()+'</main>'}
  function worldPixel(lat,lng,z){const scale=256*Math.pow(2,z),x=(lng+180)/360*scale,s=Math.sin(lat*Math.PI/180),y=(0.5-Math.log((1+s)/(1-s))/(4*Math.PI))*scale;return{x,y,scale}}
