  function coverPhotosOf(r){r=r||{};const list=(Array.isArray(r.coverImages)?r.coverImages:[]).map(x=>typeof x==="string"?{url:x,thumbUrl:x}:x&&x.url?{url:String(x.url),thumbUrl:String(x.thumbUrl||x.url)}:null).filter(Boolean);if(!list.length&&(r.imageUrl||r.image))list.push({url:String(r.imageUrl||r.image),thumbUrl:String(r.imageThumbUrl||r.imageUrl||r.image)});return list.slice(0,MAX_COVER_PHOTOS)}
  function coverDraft(){if(!state.coverDraft||state.coverDraft.restaurantId!==restaurantId())state.coverDraft={restaurantId:restaurantId(),photos:coverPhotosOf(state.restaurant)};return state.coverDraft.photos}
  function coverGalleryMarkup(){const photos=coverDraft(),edit=permission("profile");return photos.map((x,i)=>'<figure class="cover-tile'+(i===0?' first':'')+'"><img src="'+h(x.thumbUrl||x.url)+'" alt="Cover photo '+(i+1)+'" loading="lazy">'+(i===0?'<span class="cover-badge">First</span>':'')+(edit?'<div class="cover-tools">'+(i>0?'<button type="button" class="cover-tool" data-action="cover-first" data-index="'+i+'">Make first</button>':'')+'<button type="button" class="cover-tool danger" data-action="cover-remove" data-index="'+i+'" aria-label="Remove photo '+(i+1)+'">Remove</button></div>':'')+'</figure>').join("")+(edit&&photos.length<MAX_COVER_PHOTOS?'<label class="cover-add'+(coverUploading?' busy':'')+'" for="restaurant-image">'+(coverUploading?'<span>Uploading…</span>':'<strong>+</strong><span>Add photo</span>')+'<input id="restaurant-image" type="file" accept="image/jpeg,image/png,image/webp"'+(coverUploading?' disabled':'')+' hidden></label>':'')}
  function refreshCoverGallery(){const node=document.getElementById("cover-gallery");if(node)node.innerHTML=coverGalleryMarkup();const count=document.getElementById("cover-count");if(count)count.textContent=coverDraft().length+"/"+MAX_COVER_PHOTOS}
  async function addCoverPhoto(file){if(!file||coverUploading)return;if(coverDraft().length>=MAX_COVER_PHOTOS){toast("You can add up to "+MAX_COVER_PHOTOS+" photos. Remove one to add another.","danger");return}coverUploading=true;refreshCoverGallery();let url="",thumbUrl="";try{const path="restaurants/"+restaurantId()+"/users/"+state.session.uid+"/cover/"+Date.now()+".jpg",prepared=await prepareUploadFile(file,1400,.8),preparedThumb=await prepareThumbFile(file);url=await storageUpload(prepared,path);thumbUrl=await storageUpload(preparedThumb,thumbPath(path),"thumb");coverDraft().push({url,thumbUrl,fresh:true});toast("Photo added. Tap Save to show it to customers.","success")}catch(e){if(url)storageDelete(url).catch(()=>false);toast("Photo upload failed. "+friendly(e),"danger")}finally{coverUploading=false;refreshCoverGallery()}}
